}

Method.Source:
/// <summary>
/// Purchase order number parameter
/// </summary>
/// <param name = "_salesId">salesId</param>
/// <returns>salesId</returns>
[
    DataMemberAttribute("@MET:SalesOrderNum"),
    SysOperationLabelAttribute(literalStr("@SYS9694")),
    SysOperationControlVisibilityAttribute(false)

]
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;

    return salesId;
}

/// <summary>
/// Reprint parameter
/// </summary>
/// <param name = "_isReprint">Reprint</param>
/// <returns>Boolean value</returns>
[
    DataMemberAttribute("@MET:IsReprint"),
    SysOperationLabelAttribute(literalStr("@MET:Reprint")),
    SysOperationControlVisibilityAttribute(false)

]
public boolean parmIsRePrint(boolean _isReprint = isReprint)
{
    isReprint = _isReprint;

    return isReprint;
}
